// Keyboard-only journeys use the real dialogs and callbacks, with a simulated DOM/focus.
async function press(key,extra={}){const event={key,target:document.activeElement||el('game'),repeat:false,preventDefault(){},...extra};listeners.keydown(event);await Promise.resolve();await Promise.resolve();return event}
async function tabTo(test){for(let i=0;i<350;i++){if(test(document.activeElement))return;await press('Tab')}throw Error('Keyboard cannot reach the requested control')}
async function waitFor(test){for(let i=0;i<150;i++){if(test())return;await new Promise(resolve=>setTimeout(resolve,10))}throw Error('Keyboard action did not complete')}
